class Solution {
    /**
     * @param {number[][]} grid
     * @return {number}
     */
    numEnclaves(grid) {
        const ROWS = grid.length,
            COLS = grid[0].length;
        const visit = Array.from({ length: ROWS }, () =>
            Array(COLS).fill(false),
        );
        const direct = [0, 1, 0, -1, 0];

        const dfs = (r, c) => {
            if (
                r < 0 ||
                c < 0 ||
                r === ROWS ||
                c === COLS ||
                grid[r][c] === 0 ||
                visit[r][c]
            ) {
                return 0;
            }
            visit[r][c] = true;
            let res = 1;
            for (let d = 0; d < 4; d++) {
                res += dfs(r + direct[d], c + direct[d + 1]);
            }
            return res;
        };

        let land = 0,
            borderLand = 0;
        for (let r = 0; r < ROWS; r++) {
            for (let c = 0; c < COLS; c++) {
                land += grid[r][c];
                if (
                    grid[r][c] === 1 &&
                    !visit[r][c] &&
                    (r === 0 || r === ROWS - 1 || c === 0 || c === COLS - 1)
                ) {
                    borderLand += dfs(r, c);
                }
            }
        }
        return land - borderLand;
    }
}
