		return res
	}

	land, borderLand := 0, 0

	for r := 0; r < ROWS; r++ {
		for c := 0; c < COLS; c++ {
			land += grid[r][c]

			key := [2]int{r, c}
			if grid[r][c] == 1 && !visit[key] && (c == 0 || c == COLS-1 || r == 0 || r == ROWS-1) {
				borderLand += dfs(r, c)
			}
		}
	}

	return land - borderLand
}

