impl Solution {
    pub fn num_enclaves(grid: Vec<Vec<i32>>) -> i32 {
        let rows = grid.len();
        let cols = grid[0].len();
        let mut visit = vec![vec![false; cols]; rows];
        let directions = [(0, 1), (0, -1), (1, 0), (-1, 0)];

        let mut land = 0;
        let mut border_land = 0;

        for r in 0..rows {
            for c in 0..cols {
                land += grid[r][c];
                if grid[r][c] == 1 && !visit[r][c]
                    && (r == 0 || r == rows - 1 || c == 0 || c == cols - 1)
                {
                    border_land += Self::dfs(&grid, &mut visit, r, c, &directions);
                }
            }
        }

        land - border_land
    }

    fn dfs(
        grid: &Vec<Vec<i32>>,
        visit: &mut Vec<Vec<bool>>,
        r: usize,
        c: usize,
        directions: &[(i32, i32)],
    ) -> i32 {
        let rows = grid.len();
        let cols = grid[0].len();

        if r >= rows || c >= cols || grid[r][c] == 0 || visit[r][c] {
            return 0;
        }

        visit[r][c] = true;
        let mut res = 1;

        for (dr, dc) in directions {
            let nr = r as i32 + dr;
            let nc = c as i32 + dc;
            if nr >= 0 && nc >= 0 {
                res += Self::dfs(grid, visit, nr as usize, nc as usize, directions);
            }
        }

        res
    }
}

